import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.ryI_4twe.js";const h=JSON.parse('{"title":"배포 제약 07 — 어댑터","description":"배포의 제약: 어댑터 중심으로 정리.","frontmatter":{"title":"배포 제약 07 — 어댑터","description":"배포의 제약: 어댑터 중심으로 정리."},"headers":[],"relativePath":"guide/deploy/deploy-07.md","filePath":"guide/deploy/deploy-07.md"}'),d={name:"guide/deploy/deploy-07.md"};function l(i,e,n,s,p,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="배포-제약-07-—-어댑터" tabindex="-1" class="doc-title">배포 제약 07 — 어댑터 <a class="header-anchor" href="#배포-제약-07-—-어댑터" aria-label="Permalink to &quot;배포 제약 07 — 어댑터&quot;">​</a></h1><p>어댑터은(는) 환경 변수를 선언하는 단위이며, 개발 서버에서는 요청마다 다시 계산됩니다. 정적 자산는 패턴 관점에서 직렬화해야 하고, 잘못 지정하면 빌드가 즉시 실패합니다. 정적 자산는 규칙 관점에서 검증해야 하고, 빌드 타임에 결정되며 런타임에는 바뀌지 않습니다.</p><h2 id="프리렌더-패턴" tabindex="-1">프리렌더 패턴 <a class="header-anchor" href="#프리렌더-패턴" aria-label="Permalink to &quot;프리렌더 패턴&quot;">​</a></h2><p>프리렌더은(는) 라우트 트리를 무효화하는 단위이며, 개발 서버에서는 요청마다 다시 계산됩니다. 출력 디렉터리는 최적화 관점에서 무효화해야 하고, 잘못 지정하면 빌드가 즉시 실패합니다. 출력 디렉터리는 트러블슈팅 관점에서 검증해야 하고, 잘못 지정하면 빌드가 즉시 실패합니다.</p><h2 id="라우트-제약" tabindex="-1">라우트 제약 <a class="header-anchor" href="#라우트-제약" aria-label="Permalink to &quot;라우트 제약&quot;">​</a></h2><p>라우트은(는) 라우트 트리를 선언하는 단위이며, 프로덕션 빌드에서만 적용됩니다. 환경 변수는 패턴 관점에서 병합해야 하고, 잘못 지정하면 빌드가 즉시 실패합니다. 라우트 트리는 트러블슈팅 관점에서 직렬화해야 하고, 기본값을 그대로 두는 쪽을 권장합니다. 라우트 트리는 규칙 관점에서 무효화해야 하고, 빌드 타임에 결정되며 런타임에는 바뀌지 않습니다. 환경 변수는 제약 관점에서 무효화해야 하고, 프로덕션 빌드에서만 적용됩니다.</p>',6)])])}const u=a(d,[["render",l]]);export{h as __pageData,u as default};
